<?php
 namespace QQWorld\Framework\Test\Unit; class ShellTest extends \PHPUnit\Framework\TestCase { protected $commandRenderer; protected $logger; protected function setUp() { $this->logger = $this->getMockBuilder(\Psr\Log\LoggerInterface::class) ->disableOriginalConstructor() ->getMock(); $this->commandRenderer = new \QQWorld\Framework\Shell\CommandRenderer(); } protected function _testExecuteCommand(\QQWorld\Framework\Shell $shell, $command, $commandArgs, $expectedResult) { $this->expectOutputString(''); $actualResult = $shell->execute($command, $commandArgs); $this->assertEquals($expectedResult, $actualResult); } public function testExecute($command, $commandArgs, $expectedResult) { $this->_testExecuteCommand( new \QQWorld\Framework\Shell($this->commandRenderer, $this->logger), $command, $commandArgs, $expectedResult ); } public function testExecuteLog($command, $commandArgs, $expectedResult, $expectedLogRecords) { $quoteChar = substr(escapeshellarg(' '), 0, 1); foreach ($expectedLogRecords as $logRecordIndex => $expectedLogMessage) { $expectedLogMessage = str_replace('`', $quoteChar, $expectedLogMessage); $this->logger->expects($this->at($logRecordIndex)) ->method('info') ->with($expectedLogMessage); } $this->_testExecuteCommand( new \QQWorld\Framework\Shell($this->commandRenderer, $this->logger), $command, $commandArgs, $expectedResult ); } public function executeDataProvider() { return [ 'STDOUT' => ['php -r %s', ['echo 27181;'], '27181', ['php -r `echo 27181;` 2>&1', '27181']], 'STDERR' => [ 'php -r %s', ['fwrite(STDERR, 27182);'], '27182', ['php -r `fwrite(STDERR, 27182);` 2>&1', '27182'], ], 'piping STDERR -> STDOUT' => [ 'php -r %s|php -r %s', ['fwrite(STDERR, 27183);', 'echo fgets(STDIN);'], '27183', ['php -r `fwrite(STDERR, 27183);` 2>&1|php -r `echo fgets(STDIN);` 2>&1', '27183'], ], 'piping STDERR -> STDERR' => [ 'php -r %s | php -r %s', ['fwrite(STDERR, 27184);', 'fwrite(STDERR, fgets(STDIN));'], '27184', ['php -r `fwrite(STDERR, 27184);` 2>&1 | php -r `fwrite(STDERR, fgets(STDIN));` 2>&1', '27184'], ] ]; } public function testExecuteFailure() { $shell = new \QQWorld\Framework\Shell($this->commandRenderer, $this->logger); $shell->execute('non_existing_command'); } public function testExecuteFailureDetails($command, $commandArgs, $expectedError) { try { $commandArgs[count($commandArgs) - 1] .= ' exit(42);'; $this->testExecute($command, $commandArgs, ''); } catch (\QQWorld\Framework\Exception\LocalizedException $e) { $this->assertInstanceOf('Exception', $e->getPrevious()); $this->assertEquals($expectedError, $e->getPrevious()->getMessage()); $this->assertEquals(42, $e->getPrevious()->getCode()); } } } 